import{j as a}from"./index-BqRRujd_.js";const o={company:"[Company legal name]",product:"Bintro",email:"[legal or privacy email]",supportEmail:"hello@bintroapp.com",address:"[Mailing address]",governingState:"Texas",venue:"[County], Texas",effectiveDate:"[Effective date]"},h=Object.values(o).some(n=>n.includes("[")),{company:t,product:e,email:r,address:i,governingState:c,venue:u}=o,m=[{heading:"1. Agreement",paragraphs:[`These Terms of Service ("Terms") are an agreement between you (the business using ${e}, and anyone using it on the business's behalf) and ${t} ("we", "us"). By creating an account, scanning, or otherwise using ${e}, you agree to these Terms, our Privacy Policy and our End-User License Agreement.`,`If you use ${e} for a business, you confirm you have authority to bind that business.`]},{heading:"2. The service",paragraphs:[`${e} is inventory and budgeting software for small businesses: scanning stock in and out, purchase orders, delivery check-in, sales reports, budgets and optional connections to other software such as Square and QuickBooks.`,"Features differ by plan. We may change, add or remove features. If we remove a feature that is central to your paid plan, we will tell you in advance and you may cancel."]},{heading:"3. Plans, billing and cancellation",paragraphs:["Paid plans are billed in advance, monthly or yearly, through our payment processor. Prices are shown in the app before you subscribe. Plans renew automatically until canceled.","You can pause a plan for 1 to 3 months or cancel at any time in Settings → Account & billing. A cancellation takes effect at the end of the current billing period, and you keep access until then. Except where the law requires otherwise, payments are not refundable.","Free trials and pilot programs end on the date shown in the app. When a pilot or trial ends without a paid plan, the account moves to the Free plan; your data is kept.","We may change prices with at least 30 days' notice. A new price applies from your next renewal after the notice."]},{heading:"4. Your data",paragraphs:[`You own the data you put into ${e} (products, counts, costs, vendors, expenses, staff names and files you upload). You give us permission to store and process it only to run, secure and improve the service for you, as described in our Privacy Policy.`,"You are responsible for the accuracy of your data and for keeping your own records for tax and legal purposes. You can ask us for a full export of your data at any time while your account is open."]},{heading:"5. AI features",paragraphs:[`Some features use artificial intelligence to read photos and documents (labels, invoices, receipts, sales reports) and to suggest prices. AI results can be wrong. ${e} shows results for you to review before they change your inventory, and you are responsible for checking them.`,"Price checks look at suppliers, professional distributors and brand websites. Prices found are estimates and may not match what your supplier charges you."]},{heading:"6. Connected services",paragraphs:[`When you connect another service (for example Square or QuickBooks), you authorize ${e} to read and write the data that connection allows. Those services are governed by their own terms, and we are not responsible for them. You can disconnect at any time.`]},{heading:"7. Acceptable use",paragraphs:[`Do not misuse ${e}: no unlawful use, no attempts to access other customers' data, no reverse engineering except where the law allows, no overloading or disrupting the service, and no uploading of malware or content you have no right to use.`,"We may suspend accounts that break these rules or put the service or other customers at risk."]},{heading:"8. Availability",paragraphs:[`We work to keep ${e} available and your data backed up, but the service is provided "as is" and "as available". We do not promise it will be uninterrupted or error-free.`]},{heading:"9. Disclaimers",paragraphs:[`${e} is a business tool, not tax, legal or accounting advice. Tax groupings and budget figures are there to help you and your accountant; confirm them with a professional.`,"To the fullest extent the law allows, we disclaim all implied warranties, including merchantability, fitness for a particular purpose and non-infringement."]},{heading:"10. Limitation of liability",paragraphs:[`To the fullest extent the law allows, ${t} is not liable for indirect, incidental, special, consequential or punitive damages, or for lost profits, revenue, inventory or data. Our total liability for any claim relating to ${e} is limited to the amount you paid us in the 12 months before the claim.`]},{heading:"11. Ending the agreement",paragraphs:["You may stop using the service and cancel at any time. We may end these Terms or suspend the service if you materially breach them. After an account is closed, we keep your data for 30 days so you can export it, then delete it, except where we must keep records by law."]},{heading:"12. Changes to these Terms",paragraphs:["We may update these Terms. If a change is material, we will tell you in the app or by email at least 30 days before it takes effect. Continuing to use the service after that means you accept the new Terms."]},{heading:"13. Governing law",paragraphs:[`These Terms are governed by the laws of the State of ${c}, without regard to conflict-of-law rules. Disputes will be heard in the state or federal courts located in ${u}, and both parties consent to that venue.`]},{heading:"14. Contact",paragraphs:[`${t} · ${i} · ${r}`]}],y=[{heading:"Summary",paragraphs:[`${e} stores the business data you put in so the app can work. We don't sell your data and we don't use it for advertising. Photos you send to the AI readers are processed and not kept.`]},{heading:"What we collect",paragraphs:["Business details: business name, type, email, phone, address, website and ordering email.","Inventory and money data: products, barcodes, counts, costs and prices, vendors, purchase orders, deliveries, expenses, budgets and calendar events.","Staff names: the names your team picks before scanning, used to show who logged each change.","Sign-in: the name, email address and Google account ID of each person you allow to sign in, when they last signed in, and a sign-in session record for each browser. We never see Google passwords.","Account and billing: plan, billing email and owner name. Card details are handled by our payment processor (Stripe); we only see the card brand and last 4 digits.","Files you upload: invoices, receipts, sales reports, stock lists and product photos, used to read the information you asked for.","Connected services: if you connect Square or QuickBooks, the access tokens they issue and the data needed for the connection (catalog items, inventory counts, sales, expenses).","Device settings: a few preferences (such as the last staff name, palette and tip settings) are saved in your browser on that device only."]},{heading:"What we don't collect",paragraphs:[`${e} does not collect your clients' personal information, does not use advertising trackers, and does not sell or rent data to anyone.`]},{heading:"How we use it",paragraphs:["To run the features you use: tracking stock, building orders, checking deliveries in, reading documents, budgets, reports and insight emails.","To bill your plan, provide support, keep the service secure and fix problems.","To send the emails you turn on, such as restock lists, purchase orders and weekly or monthly reports."]},{heading:"Who processes data for us",paragraphs:["We use service providers who process data only to provide their service to us:","Netlify (hosting and database) · Google (sign-in) · Anthropic (AI reading of photos and documents, and price checks) · Stripe (payments) · Resend or SendGrid (email sending) · barcode lookup services such as Open Beauty Facts, Open Food Facts, UPCitemdb and Open Library (only the barcode is sent).","Square and QuickBooks receive data only when you connect them, and only what the connection needs.","We may also share information if required by law, to protect our rights or users, or as part of a merger or sale of the business, in which case this policy continues to apply."]},{heading:"AI processing",paragraphs:["When you use a photo or document feature, the image or file is sent to our AI provider to read it, and the result comes back to you for review. We do not store the photo in Bintro unless you attach it to a record. Our AI provider does not use this data to train its models under its commercial terms."]},{heading:"How long we keep it",paragraphs:["We keep your data while your account is open. After you close your account, we keep it for 30 days so you can export it, then delete it, except records we must keep by law (such as billing records)."]},{heading:"Security",paragraphs:["Data is sent over encrypted connections (HTTPS) and stored with our hosting provider. Access tokens for connected services are stored on the server and never shown in the app. No system is perfectly secure; we will notify you as the law requires if a breach affects your data."]},{heading:"Your choices and rights",paragraphs:[`You can view and correct your data in the app, ask us for an export, disconnect connected services at any time, and turn off report emails in Settings. To ask for a copy or deletion of your data, email ${r}. Depending on where you live (for example Texas or California), you may have additional rights, which we will honor.`]},{heading:"Children",paragraphs:[`${e} is a business tool and is not directed to children under 13.`]},{heading:"Changes",paragraphs:["We will post updates here and tell you in the app or by email before a material change takes effect."]},{heading:"Contact",paragraphs:[`${t} · ${i} · ${r}`]}],f=[{heading:"1. License",paragraphs:[`${t} grants you a limited, non-exclusive, non-transferable, revocable license to use the ${e} software, on the devices of your business and its staff, for your internal business purposes during your subscription, under this End-User License Agreement ("EULA") and our Terms of Service.`]},{heading:"2. Ownership",paragraphs:[`The software, its design, and all related intellectual property are owned by ${t} and its licensors. This EULA gives you a right to use the software, not ownership of it. Your data remains yours.`]},{heading:"3. Restrictions",paragraphs:["You may not copy, modify, distribute, sell, sublicense or rent the software; reverse engineer or decompile it except where the law expressly allows; remove proprietary notices; or use it to build a competing product."]},{heading:"4. Third-party integrations",paragraphs:[`${e} can connect to third-party services such as Square and QuickBooks Online. Your use of those services is governed by their own agreements. ${t} is not affiliated with, and is not endorsed by, Intuit Inc. or Block, Inc. QuickBooks is a trademark of Intuit Inc.; Square is a trademark of Block, Inc.`]},{heading:"5. Updates",paragraphs:["We may update the software from time to time. Updates are covered by this EULA."]},{heading:"6. Termination",paragraphs:["This license ends when your subscription ends or if you breach this EULA. When it ends, you must stop using the software. Sections on ownership, disclaimers and limitation of liability survive."]},{heading:"7. Disclaimer and liability",paragraphs:['The software is provided "as is". The disclaimers and limitation of liability in our Terms of Service apply to this EULA.']},{heading:"8. Governing law",paragraphs:[`This EULA is governed by the laws of the State of ${c}.`]},{heading:"9. Contact",paragraphs:[`${t} · ${i} · ${r}`]}],p=[{href:"/terms",label:"Terms of Service"},{href:"/privacy",label:"Privacy Policy"},{href:"/eula",label:"End-User License Agreement"}];function b({title:n,sections:l}){return a.jsx("main",{className:"min-h-screen bg-page text-ink",children:a.jsxs("div",{className:"max-w-[720px] mx-auto px-5 py-10",children:[a.jsxs("a",{href:"/",className:"text-action font-semibold text-sm no-underline",children:["← ",o.product]}),a.jsx("h1",{className:"text-[28px] font-bold mt-4 mb-1",children:n}),a.jsxs("p",{className:"m-0 text-sm text-ink-2",children:[o.product," · ",o.company," · Effective ",o.effectiveDate]}),h&&a.jsx("p",{className:"mt-4 mb-0 rounded-xl bg-warn-tint text-warn px-4 py-3 text-sm font-semibold",children:"Draft: details in [brackets] still need to be filled in, and this page should be reviewed by a lawyer before it's relied on."}),l.map(s=>a.jsxs("section",{className:"mt-7",children:[a.jsx("h2",{className:"text-lg font-bold mb-2",children:s.heading}),s.paragraphs.map(d=>a.jsx("p",{className:"mt-0 mb-2.5 leading-relaxed text-[15px]",children:d},d))]},s.heading)),a.jsx("nav",{className:"mt-10 pt-5 border-t border-line flex flex-wrap gap-x-5 gap-y-2 text-sm","aria-label":"Legal",children:p.map(s=>a.jsx("a",{href:s.href,className:"text-action font-semibold no-underline",children:s.label},s.href))})]})})}export{f as E,p as L,y as P,m as T,o as a,b};
